package vn.svframe.svframelib.api.crafting.outputs; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.recipes.*; import vn.svframe.svframelib.api.crafting.recipes.vmp.VanillaInventoryMapping; import net.minecraft.server.network.ServerPlayerEntity; public abstract class SVFrameRecipeOutput { public abstract SVFrameRecipeInventory applyDisplay(SVFrameBlueprintInventory input,ServerPlayerEntity player,VanillaInventoryMapping mapping); public abstract void applyResult(SVFrameRecipeInventory result,SVFrameBlueprintInventory input,SVFrameCachedResult cache,ServerPlayerEntity player,VanillaInventoryMapping mapping,int amount); public void processInventory(SVFrameRecipeInventory target,SVFrameRecipeInventory delta,int times){for(int y=0;y<delta.getHeight();y++)for(int x=0;x<delta.getWidth();x++){var s=delta.getItemAt(x,y);if(!s.isEmpty()){var c=s.copy();c.setCount(Math.max(1,c.getCount()*Math.max(1,times)));target.setItemAt(x,y,c);}}} }
